-- create schema raw_open_meteo
CREATE SCHEMA IF NOT EXISTS raw_open_meteo;

-- create raw_open_meteo.weather_daily
CREATE TABLE IF NOT EXISTS raw_open_meteo.weather_daily (
    location_key VARCHAR,
    latitude DECIMAL(9,6),
    longitude DECIMAL(9,6),
    timezone VARCHAR,
    observed_date DATE,
    temperature_2m_max DECIMAL(5,1),
    temperature_2m_min DECIMAL(5,1),
    precipitation_sum DECIMAL(6,1),
    snowfall_sum DECIMAL(6,2),
    weather_code INTEGER,
    _ingested_at TIMESTAMPTZ,
    _batch_id VARCHAR
);
COMMENT ON TABLE raw_open_meteo.weather_daily IS 'Daily aggregated historical weather per location from the Open-Meteo archive API.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.location_key IS 'Our identifier for the requested point, e.g. a borough centroid; the API itself is queried by coordinates.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.latitude IS 'Latitude of the weather grid cell the API resolved to.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.longitude IS 'Longitude of the weather grid cell the API resolved to.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.timezone IS 'IANA time zone used for the time values.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.observed_date IS 'Calendar day in the chosen time zone.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.temperature_2m_max IS 'Maximum daily air temperature 2 metres above ground.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.temperature_2m_min IS 'Minimum daily air temperature 2 metres above ground.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.precipitation_sum IS 'Total precipitation for the day.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.snowfall_sum IS 'Total snowfall for the day.';
COMMENT ON COLUMN raw_open_meteo.weather_daily.weather_code IS 'Most severe WMO weather code during the day.';
COMMENT ON COLUMN raw_open_meteo.weather_daily._ingested_at IS 'Written by ingestion.';
COMMENT ON COLUMN raw_open_meteo.weather_daily._batch_id IS 'Written by ingestion.';

